#!/usr/bin/env bash
# Bootstrap MVP DNS (dnsmasq) and NTP (chronyd) on the bastion host
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
# shellcheck disable=SC1091
source "${SCRIPT_DIR}/lib/common.sh"

EXPORT_HOSTS=false
if [[ "${1:-}" == "--export-hosts" ]]; then
  EXPORT_HOSTS=true
fi

if [[ "$EXPORT_HOSTS" == false ]]; then
  check_root
fi

load_env

generate_dnsmasq_config() {
  cat > /etc/dnsmasq.d/ocp-v.conf <<EOF
# OCP-V dark site DNS — generated by 02-bootstrap-dns-ntp.sh
# Do not edit manually; regenerate from .env

# Listen only on bastion IP
listen-address=${BASTION_IP}
bind-interfaces
no-dhcp-interface=

# Upstream disabled (dark site)
no-resolv

# Infrastructure
address=/bastion.${BASE_DOMAIN}/${BASTION_IP}
address=/registry.${BASE_DOMAIN}/${MIRROR_REGISTRY_IP}
address=/gw.${BASE_DOMAIN}/${NETWORK_GATEWAY}

# OpenShift VIPs
address=/api.${CLUSTER_NAME}.${BASE_DOMAIN}/${API_VIP}
address=/api-int.${CLUSTER_NAME}.${BASE_DOMAIN}/${API_VIP}
address=/*.apps.${CLUSTER_NAME}.${BASE_DOMAIN}/${INGRESS_VIP}

# Control plane
address=/cp01.${BASE_DOMAIN}/${CP01_IP}
address=/cp02.${BASE_DOMAIN}/${CP02_IP}
address=/cp03.${BASE_DOMAIN}/${CP03_IP}

# Workers
address=/wk01.${BASE_DOMAIN}/${WK01_IP}
address=/wk02.${BASE_DOMAIN}/${WK02_IP}

# Production services (pre-provision DNS records)
address=/dns.${BASE_DOMAIN}/${DNS_VM_IP}
address=/ntp.${BASE_DOMAIN}/${NTP_VM_IP}

# Logging
log-queries
log-facility=/var/log/dnsmasq.log
EOF
}

generate_hosts_file() {
  cat <<EOF
127.0.0.1   localhost localhost.localdomain
::1         localhost localhost.localdomain

# Infrastructure
${NETWORK_GATEWAY}  gw.${BASE_DOMAIN} gw
${BASTION_IP}       bastion.${BASE_DOMAIN} bastion
${MIRROR_REGISTRY_IP} registry.${BASE_DOMAIN} registry

# OpenShift VIPs
${API_VIP}  api.${CLUSTER_NAME}.${BASE_DOMAIN} api api-int.${CLUSTER_NAME}.${BASE_DOMAIN} api-int
${INGRESS_VIP}  console-openshift-console.apps.${CLUSTER_NAME}.${BASE_DOMAIN}
${INGRESS_VIP}  oauth-openshift.apps.${CLUSTER_NAME}.${BASE_DOMAIN}
${INGRESS_VIP}  downloads-openshift-console.apps.${CLUSTER_NAME}.${BASE_DOMAIN}

# Control plane
${CP01_IP}  cp01.${BASE_DOMAIN} cp01
${CP02_IP}  cp02.${BASE_DOMAIN} cp02
${CP03_IP}  cp03.${BASE_DOMAIN} cp03

# Workers
${WK01_IP}  wk01.${BASE_DOMAIN} wk01
${WK02_IP}  wk02.${BASE_DOMAIN} wk02

# Production services
${DNS_VM_IP}  dns.${BASE_DOMAIN} dns
${NTP_VM_IP}  ntp.${BASE_DOMAIN} ntp
EOF
}

if [[ "$EXPORT_HOSTS" == true ]]; then
  generate_hosts_file
  exit 0
fi

log_info "Bootstrapping MVP DNS/NTP on bastion (${BASTION_IP})"

# Install packages if missing
if ! command -v dnsmasq &>/dev/null; then
  log_info "Installing dnsmasq and chrony..."
  dnf install -y dnsmasq chrony bind-utils
fi

# Configure dnsmasq
generate_dnsmasq_config
log_info "dnsmasq config written to /etc/dnsmasq.d/ocp-v.conf"

# Configure chronyd (orphan mode — no upstream NTP)
cat > /etc/chrony.conf <<EOF
# OCP-V dark site NTP — orphan mode (no upstream)
local stratum 10 orphan
allow ${NETWORK_CIDR}
bindaddress ${BASTION_IP}
makestep 1.0 3
rtcsync
driftfile /var/lib/chrony/drift
logdir /var/log/chrony
EOF
log_info "chronyd configured in orphan mode"

# Firewall
if systemctl is-active firewalld &>/dev/null; then
  firewall-cmd --permanent --add-service=dns
  firewall-cmd --permanent --add-service=ntp
  firewall-cmd --reload
  log_info "Firewall rules added for DNS and NTP"
fi

# Start services
systemctl enable --now chronyd
systemctl enable --now dnsmasq

log_info "Services started"

# Verify
log_info "Verifying DNS..."
dig "@${BASTION_IP}" "registry.${BASE_DOMAIN}" +short

log_info "Verifying NTP..."
chronyc tracking

log_info ""
log_info "=== MVP DNS/NTP is operational ==="
log_info "DNS: ${BASTION_IP}:53"
log_info "NTP: ${BASTION_IP}:123"
log_info "Configure all cluster nodes to use these addresses."
log_info "Next: ./scripts/03-generate-install-config.sh"
